import urllib.request, json, re

def fetch_url(url, timeout=15):
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read().decode('utf-8', errors='ignore')
    except:
        return None

# Get more HN stories via a broader query
hn_url = "https://hn.algolia.com/api/v1/search?query=artificial+intelligence+OR+AI+model+OR+LLM+OR+OpenAI+OR+Anthropic&tags=story&hitsPerPage=30"
hn_data = fetch_url(hn_url)
hn_items = []
if hn_data:
    try:
        hn_json = json.loads(hn_data)
        for hit in hn_json.get('hits', []):
            title = hit.get('title', '')
            url = hit.get('url', '')
            author = hit.get('author', '')
            points = hit.get('points', 0)
            created = hit.get('created_at', '')[:10]
            if title:
                hn_items.append({'title': title, 'link': url, 'author': author, 'points': points, 'created': created})
    except Exception as e:
        print(f"HN parse error: {e}")
print(f"HN items: {len(hn_items)}")
for item in hn_items[:10]:
    print(f"  [{item['points']}pts] {item['title'][:70]}")
