import urllib.request, json, re, os

def fetch_url(url, timeout=15):
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0 (compatible; AI-News-Bot/1.0)'})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read().decode('utf-8', errors='ignore')
    except:
        return None

def parse_rss(xml_str):
    items = []
    if not xml_str:
        return items
    pattern = re.compile(r'<item[^>]*>(.*?)</item>', re.DOTALL)
    for match in pattern.finditer(xml_str):
        item_xml = match.group(1)
        title = re.search(r'<title[^>]*><!\[CDATA\[(.*?)\]\]></title>', item_xml, re.DOTALL)
        if not title:
            title = re.search(r'<title[^>]*>(.*?)</title>', item_xml, re.DOTALL)
        link = re.search(r'<link[^>]*>(.*?)</link>', item_xml, re.DOTALL)
        desc = re.search(r'<description[^>]*>(.*?)</description>', item_xml, re.DOTALL)
        title_text = title.group(1).strip() if title else ''
        link_text = link.group(1).strip() if link else ''
        desc_text = re.sub(r'<[^>]+>', '', desc.group(1).strip())[:200] if desc else ''
        if title_text:
            items.append({'title': title_text, 'link': link_text, 'desc': desc_text})
    return items

# --- Google News EN ---
gn_en_url = "https://news.google.com/rss/search?q=AI+OR+LLM+OR+AGI+OR+%22AI+agent%22&hl=en-US&gl=US&ceid=US:en&sortBy=publishedAt"
gn_en_xml = fetch_url(gn_en_url)
gn_en = parse_rss(gn_en_xml)

# --- Google News CN ---
import urllib.parse
cn_query = urllib.parse.quote("人工智能 OR 大模型 OR 生成式AI OR AI大模型")
gn_cn_url = f"https://news.google.com/rss/search?q={cn_query}&hl=zh-CN&gl=CN&ceid=CN:zh-Hans&sortBy=publishedAt"
gn_cn_xml = fetch_url(gn_cn_url)
gn_cn = parse_rss(gn_cn_xml)

# --- VentureBeat ---
vb_xml = fetch_url("https://venturebeat.com/category/ai/feed/")
vb = parse_rss(vb_xml)

# --- BBC ---
bbc_xml = fetch_url("https://feeds.bbci.co.uk/news/technology/rss.xml")
bbc = parse_rss(bbc_xml)

# Compile all items with source
all_items = []
for item in gn_en:
    all_items.append(('Google News EN', item['title'], item['link'], item['desc']))
for item in gn_cn:
    all_items.append(('Google News CN', item['title'], item['link'], item['desc']))
for item in vb:
    all_items.append(('VentureBeat', item['title'], item['link'], item['desc']))
for item in bbc:
    all_items.append(('BBC Tech', item['title'], item['link'], item['desc']))

# Keywords for categorization
big_tech = ['openai', 'anthropic', 'google', 'meta', 'microsoft', 'apple', 'nvidia', 'xai', 'amazon', 'byte', '字节', 'baidu', '百度', 'alibaba', '阿里', 'tencent', '腾讯', 'huawei', '华为', 'tesla', 'spacex', 'deepmind', 'stability ai', 'mistral', 'Perplexity', 'snap']
tech_keywords = ['breakthrough', 'model', 'research', 'study', 'discover', 'scientist', 'benchmark', 'training', 'architecture', 'performance', 'accuracy']
funding_keywords = ['funding', 'raises', 'round', 'invest', 'million', 'billion', 'valuation', 'Series', 'seed', 'A轮', 'B轮', '融资', '投资', '估值']
security_keywords = ['hack', 'breach', 'security', 'vulnerability', 'exploit', 'attack', 'safety', 'risk', 'threat', ' regulation', 'ban', 'policy', 'safety', '安全', '漏洞', '攻击', '监管', '整治']
product_keywords = ['launch', 'release', 'announce', 'debut', 'introduce', 'unveil', 'beta', 'available', 'product', 'app', 'service', '发布', '推出', '上线', '产品', '发布']

def categorize(title, desc):
    t = (title + ' ' + desc).lower()

    # Check funding first
    for kw in funding_keywords:
        if kw.lower() in t:
            return '融资消息'

    # Big tech
    for kw in big_tech:
        if kw.lower() in t:
            return '大厂动态'

    # Security
    for kw in security_keywords:
        if kw.lower() in t:
            return '安全事件'

    # Product
    for kw in product_keywords:
        if kw.lower() in t:
            return '新产品'

    # Tech
    for kw in tech_keywords:
        if kw.lower() in t:
            return '技术突破'

    return '其他'

categorized = {'大厂动态': [], '技术突破': [], '融资消息': [], '安全事件': [], '新产品': []}

for src, title, link, desc in all_items:
    cat = categorize(title, desc)
    if cat != '其他':
        categorized[cat].append((src, title, link, desc))

# Deduplicate by title similarity
seen_titles = set()
final = {}
for cat in categorized:
    final[cat] = []
    for src, title, link, desc in categorized[cat]:
        # Simple dedup: skip if same title (case-insensitive) already seen
        title_lower = title.lower()[:80]
        if title_lower in seen_titles:
            continue
        seen_titles.add(title_lower)
        final[cat].append((src, title, link, desc))

for cat in final:
    print(f"\n=== {cat} ({len(final[cat])}) ===")
    for src, title, link, desc in final[cat][:5]:
        print(f"  [{src}] {title[:70]}")
        print(f"   {desc[:80]}")
